import { HISTORY_CURRICULUM_DEPTH } from './curriculum-depth.js'
import { HISTORY_MAP_ATLAS } from './map-atlas.js'
import { HISTORY_SCHOOL_STANDARD } from './school-standard.js'

/**
 * TYT TARİH KÜTÜPHANESİ
 *
 * Mevcut on üst düzey müfredat düğümünü değiştirmeden, öğrencinin olayları
 * kronoloji ve neden-sonuç ilişkisiyle kuracağı alt derslere böler. İçerik
 * özellikle görselsizdir; zaman, ilişki ve karşılaştırma mevcut HTML/CSS
 * bloklarıyla anlatılır.
 */

function makeLesson(item, index) {
  const id = item.slug
  const concepts = item.concepts ?? []
  const depth = HISTORY_CURRICULUM_DEPTH[id]
  const eventBlocks = item.eventBlocks ?? []
  const atlasMap = HISTORY_MAP_ATLAS[id]
  const school = HISTORY_SCHOOL_STANDARD[id]
  const hasCustomMap = eventBlocks.some((block) => block.type === 'historical_map')
  if (!depth) throw new Error(`Tarih dersi icin mufredat derinligi eksik: ${id}`)
  if (!school) throw new Error(`Tarih dersi icin okul standardi eksik: ${id}`)
  return {
    slug: id,
    // Tarih için ayrı bir kalite standardı tanımlanana kadar mevcut
    // okuyucunun standart yayın modunu kullanır; pedagojik temel akış belge
    // içinde zaten açıkça kuruludur.
    learningMode: 'interactive',
    qualityProfile: 'history',
    placement: { examType: 'TYT', subject: 'Tarih', topic: item.topic },
    order: item.order,
    partLabel: `Kronolojik sıra ${index + 1}`,
    title: item.title,
    subtitle: item.subtitle,
    document: {
      version: 2,
      estimated_minutes: item.minutes ?? 42,
      prerequisites: [
        item.previous
          ? { topic: item.previous, why: 'Olayların hangi koşullardan doğduğunu ve kronolojik bağı kurmak için.' }
          : { topic: 'Ön bilgi zorunlu değil', why: 'Tarihi okuma yöntemi bu dersin içinde sıfırdan kurulur.' },
      ],
      outcomes: [
        `${item.shortTitle} konusunun ortaya çıkış nedenlerini açıklayabileceksin.`,
        'Olayları gerekli dönüm noktalarıyla kronolojik sıraya koyabileceksin.',
        'Sebep, olay, sonuç ve sonraki etki arasında bağ kurabileceksin.',
        'ÖSYM yorum sorularında bilgiden çıkarım yapabileceksin.',
        'Hükümdar ve önemli şahsiyetleri dönemin olaylarıyla eşleştirebileceksin.',
        'Okul yazılısında gereken tarih, kavram ve klasik neden-sonuç bilgisini kullanabileceksin.',
      ],
      sections: [
        {
          id: `${id}-once`, kind: 'opening', title: 'Konuya girmeden önce',
          lead: item.entry,
          blocks: [
            ...concepts.map((concept, conceptIndex) => ({ id: `${id}-concept-${conceptIndex}`, type: 'concept', ...concept })),
            { id: `${id}-period`, type: 'period_summary', title: item.period.title, range: item.period.range, body: item.period.body, turning_points: item.period.points },
            {
              id: `${id}-reading-frame`, type: 'memory', title: 'Bu dersi hangi soruyla okuyacaksın?',
              body: `${depth.focus} Her bilgi için “hangi ihtiyaca cevap verdi, kimin yetkisini değiştirdi, kısa ve uzun vadede ne doğurdu?” sorularını sor. Böylece tarih ve isimler birbirinden kopuk kartlar değil, açıklanabilir bir süreç olur.`,
            },
          ],
        },
        {
          id: `${id}-arka-plan`, kind: 'build', title: 'Olayın arka planı: Bu neden oldu?',
          lead: 'Tarihte bir gelişme tek bir nedenle açıklanmaz; koşullar birleşir ve bir kırılma üretir.',
          blocks: [
            { id: `${id}-background`, type: 'prose', body: item.background },
            { id: `${id}-why`, type: 'why', question: item.whyQuestion, body: item.why },
            {
              id: `${id}-background-boundary`, type: 'connection', title: 'Arka planı tek nedene indirgeme',
              body: `${item.eventLead} Bu nedenle siyasi kararı; ekonomik kaynak, toplumsal destek, coğrafi imkân ve dönemin rakipleriyle birlikte düşün. Bunlardan biri hızlandırıcı olabilir, fakat tek başına bütün sonucu açıklamayabilir.`,
              links: ['Çok nedenlilik', 'Dönemin koşulları', 'Amaç–sonuç ayrımı'],
            },
          ],
        },
        {
          id: `${id}-olay`, kind: 'deepen', title: 'Ne oldu ve neye dönüştü?',
          lead: item.eventLead,
          blocks: [
            { id: `${id}-event`, type: 'prose', body: item.event },
            { id: `${id}-timeline`, type: 'timeline', title: 'Öğrenmen gereken dönüm noktaları', intro: 'Tarihleri tek başına değil, değişimin sırasını görmek için oku.', items: item.timeline, takeaway: item.timelineTakeaway },
            ...(atlasMap && !hasCustomMap ? [atlasMap] : []),
            ...eventBlocks,
            { id: `${id}-chain`, type: 'cause_effect', title: 'Sebep → olay → sonuç → sonraki etki', steps: item.chain, inference: item.inference },
            { id: `${id}-connection`, type: 'connection', title: 'Neden önemli?', body: item.importance, links: item.links },
          ],
        },
        {
          id: `${id}-mufredat`, kind: 'deepen', title: 'Müfredatın ayrıntılı kavram haritası',
          lead: depth.focus,
          blocks: [
            {
              id: `${id}-coverage`, type: 'table', title: 'Alt kazanım → bilmen gereken → yorum sınırı',
              columns: ['Alt başlık', 'Bilmen gereken ilişki', 'Yanlış genellemeyi önleyen sınır'],
              rows: depth.coverage,
              caption: 'Her satırı üç aşamada çalış: kavramı tanı, işlevini açıkla, son sütundaki sınırı kullanarak aşırı yorumu ele.',
            },
            { id: `${id}-depth-analysis`, type: 'prose', body: depth.analysis },
            {
              id: `${id}-curriculum-method`, type: 'why',
              question: 'Bu ayrıntılar neden tek tek ezberlenmemeli?',
              body: `Çünkü ${item.shortTitle} sorularında kişi, kurum ve tarih çoğu zaman bir ipucudur. Asıl iş; coğrafya, meşruiyet, ekonomi, toplum ve askerî yapıdan hangisinin değiştiğini bulmaktır. Bir gelişmenin amacı ile gerçekleşen sonucu; kısa vadeli etkisi ile sonraki döneme bıraktığı etkiyi ayır. Böylece yeni bir belge veya daha önce görmediğin bir soru kökü geldiğinde de aynı ilişkiyi yeniden kurabilirsin.`,
            },
          ],
        },
        {
          id: `${id}-kanit`, kind: 'practice', title: 'Kanıttan sonuca: kaynak okuma laboratuvarı',
          lead: 'ÖSYM son yıllarda doğrudan adı sormaktan çok kısa bir metindeki yetkiyi, amacı, değişimi veya sınırı fark ettiriyor.',
          blocks: [
            {
              id: `${id}-source-example`, type: 'worked_example', title: 'Birincil ipuçlarını adım adım çöz',
              prompt: depth.source[0],
              steps: [
                { title: 'Metnin açık bilgisi', body: depth.source[1] },
                { title: 'Bilgiden çıkarım', body: depth.source[2] },
                { title: 'Yorumun sınırı', body: 'Metinde bulunmayan bir kurum, kesin niyet veya bütün döneme ait genelleme ekleme. Çıkarımı yalnız verilen kanıtın taşıdığı kadar genişlet.' },
              ],
              answer: depth.source[3],
              takeaway: `Doğru çözüm sırası şudur: önce metindeki somut fiili bul; sonra bunu ${item.shortTitle} konusundaki kurum veya süreçle eşleştir; son olarak “yalnızca, kesinlikle, tamamen” gibi kanıtı aşan yargıları ele.`,
            },
            {
              id: `${id}-transfer`, type: 'connection', title: 'Bilgiyi yeni soruya taşı',
              body: `Bu örnek yalnız tek bir belgeyi çözmez. Aynı akıl yürütmeyi bir antlaşma maddesi, vergi kaydı, kitabe, kongre kararı veya anayasa hükmünde de kullanabilirsin. Belgedeki özne kimin karar verdiğini, fiil hangi aracın kullanıldığını, gerekçe hangi sorunun çözülmek istendiğini, sonuç ise güç dengesinin nasıl değiştiğini gösterir. ${item.inference}`,
              links: ['Kanıtın açık bilgisi', 'Bağlama dayalı çıkarım', 'Aşırı yorumun sınırı'],
            },
          ],
        },
        {
          id: `${id}-insanlar-ve-eszaman`, kind: 'deepen', title: 'Dönemin insanları ve eş zamanlı dünya',
          lead: 'Olayı kimin döneminde, hangi kadroyla ve dünyadaki hangi gelişmelerle aynı anda yaşandığını görmeden kronoloji tamamlanmış sayılmaz.',
          blocks: [
            {
              id: `${id}-figures`, type: 'historical_figures', title: 'Hükümdarlar ve önemli şahsiyetler',
              intro: 'Kartları aç; kişiyi yalnız adıyla değil rol aldığı olay, çözdüğü sorun ve bıraktığı etkiyle eşleştir.',
              figures: school.figures,
              takeaway: 'Yazılıda veya yorum sorusunda kişiyi tanımak için biyografisinin tamamını değil, dönem–görev–olay–sonuç bağlantısını kur.',
            },
            {
              id: `${id}-same-time`, type: 'table', title: 'Aynı dönemde dünyada ne oluyordu?',
              columns: ['Bölge / alan', 'Eş zamanlı gelişme', 'Ana konuyla bağlantısı'], rows: school.sameTime,
              caption: 'Eş zamanlılık, bir olayın tek başına değil dönemin güç, ekonomi ve fikir ortamı içinde anlaşılmasını sağlar.',
            },
            {
              id: `${id}-school-exam`, type: 'exam', title: 'Okul sınavında dikkat',
              body: 'Klasik yazılı sorusunda tanım, tarih ve kişi eşleştirmesi kadar “neden?”, “sonuç?” ve “önemi nedir?” açıklaması beklenir. Aşağıdaki başlıkları tam cümleyle anlatabilmelisin.',
              patterns: school.school,
            },
          ],
        },
        {
          id: `${id}-osym`, kind: 'practice', title: 'ÖSYM gözüyle ayır ve yorumla',
          lead: 'Soruda yalnız adı değil; değişim, süreklilik, amaç ve sonucu ayırt et.',
          blocks: [
            ...(item.compare ? [{ id: `${id}-compare`, type: 'compare', interactive: true, ...item.compare }] : []),
            ...(item.practiceBlocks ?? []),
            { id: `${id}-trap`, type: 'trap', title: 'Karıştırılan nokta', ...item.trap },
            { id: `${id}-exam`, type: 'exam', title: 'ÖSYM bu konuda neyi ölçüyor?', body: item.exam.body, patterns: item.exam.patterns },
            { id: `${id}-checkpoint`, type: 'checkpoint', ...item.checkpoint },
            {
              id: `${id}-big-picture`, type: 'summary', title: 'Büyük resim',
              points: [...depth.coverage.map((entry) => `${entry[0]}: ${entry[1]}`), item.importance],
              body: `Bu konuyu tek cümlede şöyle taşı: ${item.summary}`,
            },
            {
              id: `${id}-timeline-review`, type: 'timeline', title: 'Kronolojiyi toparlayalım',
              intro: 'Son tekrarda tarihi olay adıyla değil, bir önceki gelişmenin hangi sonucunu devraldığıyla birlikte oku.',
              items: item.timeline,
              takeaway: item.timelineTakeaway,
            },
            { id: `${id}-summary`, type: 'summary', title: item.summaryTitle ?? 'Mutlaka bil', points: [...item.spots, ...school.mustKnow], body: item.summary },
            { id: `${id}-next`, type: 'next_step', body: item.next, topics: item.nextTopics },
          ],
        },
      ],
    },
  }
}

