    period: { title: 'Kuruluş dönemi', range: '1299–1453', body: 'Osman Bey dönemindeki uç beyliği, Orhan Bey’le kurumlaştı; Rumeli’ye geçti, Ankara Savaşı sonrası toparlandı ve İstanbul’un fethiyle imparatorluk niteliği kazandı.', points: ['Koyunhisar', 'Bursa’nın alınması', 'Rumeli’ye geçiş', 'Ankara Savaşı ve Fetret', 'İstanbul’un fethi'] },
